SELECT 
FROM sys_process_orchestration_config


        AND business_config_id = #{businessConfigId}


        AND current_process_def_key LIKE CONCAT('%', #{currentProcessDefKey}, '%')


        AND current_process_def_unique_key = #{currentProcessDefUniqueKey}


        AND current_process_system = #{currentProcessSystem}


        AND next_process_def_key LIKE CONCAT('%', #{nextProcessDefKey}, '%')


        AND next_process_def_unique_key = #{nextProcessDefUniqueKey}


        AND next_process_system = #{nextProcessSystem}


        AND trigger_event = #{triggerEvent}


        AND condition_expression LIKE CONCAT('%', #{conditionExpression}, '%')


        AND priority = #{priority}


        AND is_active = #{isActive}


        AND create_user_id = #{createUserId}


        AND update_user_id = #{updateUserId}


        AND create_time >= #{createTime}


        AND update_time >= #{updateTime}


ORDER BY priority ASC, create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

